**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <set>
using namespace std;

int main() {
    ifstream plik("napisy.txt");
    string s;
    string maxNapis;
    int maxRedukcja = 0;
    while (plik >> s) {
        set<char> seen;
        string wynik = "";
        for (char c : s) {
            if (seen.find(c) == seen.end()) {
                wynik += c;
                seen.insert(c);
            }
        }
        int redukcja = s.length() - wynik.length();
        cout << s << " -> " << wynik << " (" << s.length() << " -> " << wynik.length() << ")" << endl;
        if (redukcja > maxRedukcja) {
            maxRedukcja = redukcja;
            maxNapis = s;
        }
    }
    cout << "Napis z najwieksza redukcja: " << maxNapis << " (usunieto " << maxRedukcja << " znakow)" << endl;
    return 0;
}
```

**Wyjasnienie**: `set<char>` przechowuje unikalne znaki. Sprawdzenie `find() == end()` gwarantuje dodanie tylko pierwszego wystapienia.

